<?php use App\Core\Security; ?><h4>منابع مجاز محصول</h4><p><strong><?=Security::e($product['product_code'])?></strong> — <?=Security::e($product['product_name'])?></p><form method="post"><input type="hidden" name="_csrf" value="<?=Security::e(Security::csrf())?>"><table class="table table-bordered"><thead><tr><th>انتخاب</th><th>تأمین‌کننده</th><th>شماره منبع</th><th>مورد انتظار</th></tr></thead><tbody><?php foreach($suppliers as $s):$x=$sources[(int)$s['id']]??null;?><tr><td><input type="checkbox" name="sources[<?=$s['id']?>][expected]" value="1" <?=$x?'checked':''?>></td><td><?=Security::e($s['name'])?></td><td><input type="number" min="1" max="99" name="sources[<?=$s['id']?>][source_no]" value="<?=Security::e($x['source_no']??1)?>" class="form-control"></td><td><?=$x?'بله':'خیر'?></td></tr><?php endforeach;?></tbody></table><button class="btn btn-primary">ذخیره منابع</button></form>